"""Game-native names, not expected strings generated by our formatter."""
import json
from pathlib import Path
import unittest

from ccz_randomizer import app
from ccz_randomizer.rules.skill_defaults import profile_skill_defaults
from ccz_randomizer.rules.skill_scores import resolve_setting
from ccz_randomizer.runtime.skill_memory import catalog_skill_name, format_skill_name


FIXTURE = Path(__file__).parents[1] / "fixtures/skill_display_1104.json"


class GameSkillDisplayTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.game = json.loads(FIXTURE.read_text(encoding="utf-8"))

    def test_all_255_native_definitions_match_live_formatter(self):
        for row in self.game["catalog"]:
            with self.subTest(skill=row["id"]):
                name = format_skill_name(
                    row["baseName"], row["formatType"], row["parameter"],
                    strategy_name=self.game["strategyNames"].get(str(row["parameter"]), ""),
                    **self.game["tables"],
                )
                self.assertEqual(row["name"], name)

    def test_all_active_editor_names_match_game(self):
        # Parameters can change on randomization. Use the configured editor
        # parameters, independently rendered by the native game function.
        expected = {row["id"]: row["name"] for row in self.game["editorCatalog"]}
        for row in app.runtime_skill_catalog_rows():
            self.assertEqual(expected[row["id"]], row["name"])
        catalog = {row[0] for row in app.skill_score_catalog()}
        self.assertIn("弱点攻击", catalog)
        self.assertNotIn("弱点攻击 移动", catalog)

    def test_weak_point_bounds_follow_native_and_keep_other_abilities(self):
        names = self.game["tables"]["ability_names"]
        for parameter in range(256):
            expected = "弱点攻击" + (" " + names[parameter] if 1 <= parameter <= 5 else "")
            self.assertEqual(expected, format_skill_name(
                "弱点攻击", 8, parameter, **self.game["tables"]))
            self.assertEqual(expected.replace(" ", "-"), app.decode_equipment_effect(0x70, parameter))

    def test_source_ability_is_clamped_as_in_native_formatter(self):
        # Verified against native 0x423D2C / 0x423D47.
        for parameter, expected in ((0, "能力辅助 攻→士"), (15, "能力辅助 攻→全能力"),
                                    (81, "能力辅助 攻→攻"), (255, "能力辅助 攻→全能力")):
            self.assertEqual(expected, format_skill_name(
                "能力辅助", 6, parameter, **self.game["tables"]))

    def test_empty_strategy_does_not_invent_a_numeric_name(self):
        self.assertEqual("策略反击", format_skill_name(
            "策略反击", 7, 144, strategy_name="", **self.game["tables"]))

    def test_previously_installed_catalog_is_corrected_without_rewriting_it(self):
        row = dict(id=84, name="弱点攻击 移动", baseName="弱点攻击", formatType=8, parameter=6)
        data = dict(runtimeCatalog=[row], defaults=[[row["name"], 2, "强力", "WARRIOR"]])
        self.assertEqual("弱点攻击", catalog_skill_name(row))
        self.assertEqual((("弱点攻击", 2, "强力", "WARRIOR"),), profile_skill_defaults(data))
        self.assertEqual("弱点攻击 移动", row["name"])

    def test_old_custom_score_and_type_follow_the_display_correction(self):
        from ccz_randomizer.rules.editor import skill_override
        for old in ("弱点攻击 移动", "弱点攻击-移动"):
            self.assertEqual(3.5, resolve_setting({old: 3.5}, "弱点攻击", 0))
            self.assertEqual("WARRIOR", resolve_setting({old: "WARRIOR"}, "弱点攻击", "NONE"))
            self.assertEqual(3.5, skill_override({old: 3.5}, "弱点攻击", 0))
        self.assertEqual(4, resolve_setting({"弱点攻击 移动": 3.5, "弱点攻击": 4}, "弱点攻击", 0))

    def test_all_equipment_ability_suffixes_match_native_output(self):
        prefixes = dict(zip(("1c", "51", "66", "6e", "70", "7a", "7b", "7c"),
                            ("HP辅助", "提升周围", "自动提升", "MP辅助", "弱点攻击", "忽视能力", "能力辅助", "能力替换")))
        for key, names in self.game["effectSuffixes"].items():
            for parameter, suffix in enumerate(names):
                with self.subTest(code=key, parameter=parameter):
                    separator = " " if key in ("7b", "7c") else "-"
                    if (key == "1c" and parameter in (5, 9)) or (key == "66" and parameter == 63):
                        separator = ""
                    expected = prefixes[key] + (separator + suffix if suffix else "")
                    self.assertEqual(expected, app.decode_equipment_effect(int(key, 16), parameter))
